# 3) Some logs include the project full name in the first lines; try mapping file basenames to repo names if available
# Also include executionsData.csv from other conf folders if present
# At this point projects keys are basenames or names from CSVs; unify by trying to match to dataset list of 107 projects
dataset_file = "ASE24_data_and_tools/ASE24_data_and_tools/datasets/finalDataset.csv"
dataset_projects = []
if os.path.exists(dataset_file):
    try:
        with open(dataset_file, newline='', encoding='utf-8') as fh:
            rdr = csv.DictReader(fh)
            for r in rdr:
                if r.get('repoName'):
                    dataset_projects.append(r['repoName'])
                elif r.get('name'):
                    dataset_projects.append(r['name'])
    except:
        pass

# Try to remap simple basenames to repoNames if basename matches suffix of repoName
remapped = {}
for proj in list(projects.keys()):
    if proj in dataset_projects:
        remapped[proj] = proj
        continue
    for d in dataset_projects:
        if d.endswith(proj) or proj.endswith(d) or proj.startswith(d) or d.startswith(proj):
            remapped[proj] = d
            break
    if proj not in remapped:
        remapped[proj] = proj

# merge according to remapped keys
merged = {}
for old, new in remapped.items():
    data = projects.get(old, {})
    if new not in merged:
        merged[new] = {}
    for k,v in data.items():
        if k not in merged[new]:
            merged[new][k] = v

# 4) Keep only projects that have all five metrics
final = {}
for name, d in merged.items():
    if all(k in d for k in ('direct','releases','libraries','dependency_edges','version_edges')):
        final[name] = {k:int(d[k]) for k in ('direct','releases','libraries','dependency_edges','version_edges')}

# If none have all five metrics, relax to those with at least direct, dependency_edges, version_edges, and fill missing release/library from executionsData.csv (already attempted)
if not final:
    for name, d in merged.items():
        if all(k in d for k in ('direct','dependency_edges','version_edges')):
            # try to coerce releases/libraries to 0 if missing
            final[name] = {
                'direct': int(d.get('direct',0)),
                'releases': int(d.get('releases',0)),
                'libraries': int(d.get('libraries',0)),
                'dependency_edges': int(d.get('dependency_edges',0)),
                'version_edges': int(d.get('version_edges',0))
            }

# Prepare values lists
def sorted_vals(key):
    return sorted([v[key] for v in final.values()])

def percentile(sorted_list, p):
    n = len(sorted_list)
    if n == 0:
        return 0.0
    if n == 1:
        return float(sorted_list[0])
    pos = p * (n - 1)
    lo = int(math.floor(pos))
    hi = int(math.ceil(pos))
    if lo == hi:
        return float(sorted_list[int(pos)])
    frac = pos - lo
    return sorted_list[lo] * (1 - frac) + sorted_list[hi] * frac

def fmt_q(x):
    if abs(x - round(x)) < 1e-9:
        return f"{int(round(x))}"
    return f"{x:.1f}"

def fmt_comma(x):
    try:
        return f"{int(x):,}"
    except:
        return str(x)

metrics = ['direct','releases','libraries','dependency_edges','version_edges']
stats = {}
for m in metrics:
    vals = sorted_vals(m)
    if not vals:
        stats[m] = (0,0,0,0,0)
        continue
    q1 = percentile(vals, 0.25)
    q2 = percentile(vals, 0.5)
    q3 = percentile(vals, 0.75)
    mn = min(vals)
    mx = max(vals)
    stats[m] = (q1,q2,q3,mn,mx)

# Output table
out = []
out.append("**Table 2: Demographics of our dataset of {n} Java projects**\\n".format(n=len(final)))
out.append("|                           |    Q1 |  Q2 |   Q3 | min |     max |")
out.append("| ------------------------- | ----: | --: | ---: | --: | ------: |")

q1,q2,q3,mn,mx = stats['direct']
out.append("| (p)’s direct dependencies | {q1:>5} | {q2:>3} | {q3:>4} | {mn:>3} | {mx:>6} |".format(
    q1=fmt_q(q1), q2=fmt_q(q2), q3=fmt_q(q3), mn=fmt_q(mn), mx=fmt_q(mx)
))

q1,q2,q3,mn,mx = stats['releases']
out.append("| releases ((N_R))          | {q1:>5} | {q2:>3} | {q3:>4} | {mn:>3} | {mx:>7} |".format(
    q1=fmt_q(q1), q2=fmt_q(q2), q3=fmt_q(q3), mn=fmt_comma(mn), mx=fmt_comma(mx)
))

q1,q2,q3,mn,mx = stats['libraries']
out.append("| libraries ((N_L))         | {q1:>5} | {q2:>3} | {q3:>4} | {mn:>3} | {mx:>5} |".format(
    q1=fmt_q(q1), q2=fmt_q(q2), q3=fmt_q(q3), mn=fmt_comma(mn), mx=fmt_comma(mx)
))

q1,q2,q3,mn,mx = stats['dependency_edges']
out.append("| dependency edges ((E_D))  | {q1:>5} | {q2:>3} | {q3:>4} | {mn:>3} | {mx:>7} |".format(
    q1=fmt_q(q1), q2=fmt_q(q2), q3=fmt_q(q3), mn=fmt_comma(mn), mx=fmt_comma(mx)
))

q1,q2,q3,mn,mx = stats['version_edges']
out.append("| versions edges ((E_V))    | {q1:>5} | {q2:>3} | {q3:>4} | {mn:>3} | {mx:>7} |".format(
    q1=fmt_q(q1), q2=fmt_q(q2), q3=fmt_q(q3), mn=fmt_comma(mn), mx=fmt_comma(mx)
))

print("\\n".join(out))
